[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$JsonPath,[string]$SchemaPath=(Join-Path $PSScriptRoot '..\references\es-resource-collection-batch-perf.v1.schema.json'))
$ErrorActionPreference='Stop';$errors=[Collections.Generic.List[string]]::new();try{$j=Get-Content -LiteralPath (Resolve-Path $JsonPath) -Raw -Encoding UTF8|ConvertFrom-Json;if($j.benchmarkId -ne 'es-resource-collection.batch-perf.v1'){[void]$errors.Add('invalid benchmarkId')};if($null -eq $j.autoParallel){[void]$errors.Add('missing autoParallel')};foreach($n in 'cold','incremental'){ $p=$j.$n;if($null -eq $p){[void]$errors.Add("missing phase: $n");continue};if($p.fileCount -lt 0 -or $p.effectiveParallel -lt 1 -or $p.elapsedMilliseconds -lt 0 -or $p.filesPerSecond -lt 0 -or $p.failedCount -lt 0){[void]$errors.Add("invalid metrics: $n")}};if($j.speedupRatio -lt 0){[void]$errors.Add('speedupRatio must be non-negative')}}catch{[void]$errors.Add($_.Exception.Message)};[ordered]@{validator='Test-ESResourceCollectionBatchPerf';path=$JsonPath;schemaPath=$SchemaPath;valid=($errors.Count -eq 0);errorCount=$errors.Count;errors=@($errors);runtimeStatus='runtime-not-run'}|ConvertTo-Json -Depth 8;if($errors.Count){exit 1}
